import { health } from '../api/client.js';

// The pulse mark: shape + word + colour. Shape and word carry the meaning; colour only reinforces.
// ok = disc, bad = diamond, busy = ring, sample = dashed ring.
export const mark = (kind) => `<span class="mark mark-${kind}" aria-hidden="true"></span>`;

const STATES = {
  checking: ['busy', 'Checking API'],
  up:       ['ok',   'API reachable'],
  down:     ['bad',  'API unreachable'],
};

let state = 'checking';
let checkedAt = '';

export function renderBadge() {
  const [kind, label] = STATES[state];
  return `<span class="badge" role="status">${mark(kind)}<span>${label}</span>${
    checkedAt ? `<span class="muted">checked ${checkedAt}</span>` : ''
  }</span>`;
}

// Real health check instead of a hardcoded "Connected". Any JSON reply counts as up.
export async function checkHealth() {
  try { await health(); state = 'up'; } catch { state = 'down'; }
  checkedAt = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  return state === 'up';
}

