import './style.css';
import { renderBadge, checkHealth, mark } from './components/StatusBadge.js';
import { listRuns, retryRun, createRun } from '../src/api/client.js';

// Demo rows. Shown only in dev, only when the runs API doesn't answer, and always labelled.
const SAMPLE_RUNS = [
  { id: 'r-1041', service: 'checkout', status: 'passed', started: '09:12', duration: '2m 41s' },
  { id: 'r-1040', service: 'billing',  status: 'failed', started: '08:58', duration: '1m 07s' },
  { id: 'r-1039', service: 'catalog',  status: 'passed', started: '08:31', duration: '3m 22s' },
  { id: 'r-1038', service: 'notify',   status: 'passed', started: '08:04', duration: '0m 51s' },
];

const STATUS_MARK = { passed: 'ok', failed: 'bad' }; // anything else (running, queued) is in flight
const HEALTH_EVERY_MS = 30_000;

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);
const $ = (sel) => document.querySelector(sel);

let source = 'loading'; // loading | live | sample | error
let runs = [];

function row(r) {
  const kind = STATUS_MARK[r.status] ?? 'busy';
  const live = source === 'live';
  return `<tr class="${kind === 'bad' ? 'is-failed' : ''}">
    <th scope="row" class="id">${esc(r.id)}</th>
    <td>${esc(r.service)}</td>
    <td><span class="status">${mark(kind)}${esc(r.status)}</span></td>
    <td class="num">${esc(r.started)}</td>
    <td class="num">${esc(r.duration)}</td>
    <td class="act"><button class="btn btn-quiet retry" data-run="${esc(r.id)}"
      ${live ? '' : 'disabled aria-describedby="notice"'}
      aria-label="Retry ${esc(r.id)}">Retry</button></td>
  </tr>`;
}

const skeleton = () => Array.from({ length: 4 }, () =>
  `<tr class="skeleton" aria-hidden="true">${'<td><span></span></td>'.repeat(6)}</tr>`).join('');

const message = (kind, text) =>
  `<tr><td colspan="6" class="empty"><span class="status">${mark(kind)}${text}</span></td></tr>`;

function renderRuns() {
  const body = $('#runs');
  $('#table').setAttribute('aria-busy', String(source === 'loading'));
  if (source === 'loading') body.innerHTML = skeleton();
  else if (source === 'error') body.innerHTML = message('bad', "Couldn't load runs: the runs API isn't responding. Reload to try again.");
  else if (!runs.length) body.innerHTML = message('busy', 'No runs yet. Start one with New run.');
  else body.innerHTML = runs.map(row).join('');

  $('#notice').hidden = source !== 'sample';
  $('#new-run').disabled = source !== 'live';
  $('#count').textContent = source === 'live' || source === 'sample'
    ? `${runs.length} ${runs.length === 1 ? 'run' : 'runs'}` : '';
}

function say(kind, text) {
  $('#feedback').innerHTML = `<span class="status">${mark(kind)}${esc(text)}</span>`;
}

// Actions report what actually happened. A non-2xx reply is a failure, never a silent success.
async function act(button, busyLabel, request, done) {
  const label = button.textContent;
  button.disabled = true;
  button.textContent = busyLabel;
  try {
    const res = await request();
    if (!res.ok) throw new Error(`the API returned ${res.status}`);
    say('ok', done);
  } catch (err) {
    say('bad', `${label} failed: ${err.message}.`);
  } finally {
    button.disabled = false;
    button.textContent = label;
  }
}

async function loadRuns() {
  try {
    runs = await listRuns();
    source = 'live';
  } catch {
    // ponytail: dev-only fallback so the demo still shows a table; a prod build shows the error state.
    runs = import.meta.env.DEV ? SAMPLE_RUNS : [];
    source = import.meta.env.DEV ? 'sample' : 'error';
  }
  renderRuns();
}

async function refreshBadge() {
  await checkHealth();
  $('#badge').innerHTML = renderBadge();
}

export function render() {
  $('#app').innerHTML = `
    <header class="bar">
      <div class="title">
        <h1>pulse</h1>
        <span class="muted">Deploy runs</span>
      </div>
      <div class="tools">
        <span id="badge">${renderBadge()}</span>
        <button id="new-run" class="btn btn-primary" disabled aria-describedby="notice">New run</button>
      </div>
    </header>
    <main>
      <p id="notice" class="notice" hidden>
        ${mark('sample')}
        <span><strong>Sample data.</strong> The runs API didn't respond, so these rows are
        placeholders and Retry and New run are off until it's connected.</span>
      </p>
      <p id="feedback" class="feedback" role="status" aria-live="polite"></p>
      <div class="table-wrap" role="region" aria-labelledby="runs-h" tabindex="0">
        <table id="table">
          <caption><h2 id="runs-h">Recent runs</h2><span id="count" class="muted"></span></caption>
          <thead><tr>
            <th scope="col">Run</th><th scope="col">Service</th><th scope="col">Status</th>
            <th scope="col" class="num">Started</th><th scope="col" class="num">Duration</th>
            <th scope="col" class="act"><span class="sr-only">Actions</span></th>
          </tr></thead>
          <tbody id="runs"></tbody>
        </table>
      </div>
    </main>`;

  $('#runs').addEventListener('click', (e) => {
    const b = e.target.closest('.retry');
    if (b) act(b, 'Retrying', () => retryRun(b.dataset.run), `Retry requested for ${b.dataset.run}.`);
  });
  $('#new-run').addEventListener('click', (e) =>
    // Request body is the backend ticket's call; the UI only reports the outcome.
    act(e.currentTarget, 'Starting', () => createRun({}), 'New run requested.'));

  renderRuns();
  loadRuns();
  refreshBadge();
  setInterval(refreshBadge, HEALTH_EVERY_MS);
}

render();

