/* Tokens: OKLCH, neutrals tinted to hue 250. Contrast pairs checked, see DESIGN.md. */
:root {
  color-scheme: dark;
  --bg: oklch(0.19 0.012 250);
  --surface: oklch(0.225 0.012 250);
  --failed-row: oklch(0.245 0.03 25);
  --line: oklch(0.31 0.012 250);
  --ctrl: oklch(0.54 0.015 250);
  --ink: oklch(0.95 0.006 250);
  --muted: oklch(0.75 0.012 250);
  --disabled: oklch(0.62 0.012 250);
  --accent: oklch(0.74 0.12 250);
  --on-accent: oklch(0.2 0.02 250);
  --ring: oklch(0.82 0.1 250);
  --ok: oklch(0.78 0.15 150);
  --bad: oklch(0.72 0.17 25);
  --sample: oklch(0.84 0.13 85);

  --s1: 0.25rem; --s2: 0.5rem; --s3: 0.75rem; --s4: 1rem; --s5: 1.5rem; --s6: 2.5rem;
  --fast: 150ms cubic-bezier(0.25, 1, 0.5, 1);

  font: 400 1rem/1.55 system-ui, -apple-system, "Segoe UI", sans-serif;
  background: var(--bg);
  color: var(--ink);
  -webkit-font-smoothing: antialiased;
}

* { box-sizing: border-box; }
body { margin: 0; }
::selection { background: oklch(0.45 0.1 250); }
:focus-visible { outline: 2px solid var(--ring); outline-offset: 2px; border-radius: 4px; }

.muted { color: var(--muted); }
.sr-only { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }

/* Header */
.bar {
  display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between;
  gap: var(--s3) var(--s5);
  padding: var(--s4) var(--s5);
  border-bottom: 1px solid var(--line);
}
.title { display: flex; align-items: baseline; gap: var(--s3); }
h1 { margin: 0; font-size: 1.2rem; font-weight: 650; letter-spacing: -0.01em; }
.tools { display: flex; flex-wrap: wrap; align-items: center; gap: var(--s3) var(--s4); }

main { max-width: 72rem; margin: 0 auto; padding: var(--s5); }

/* The pulse mark. Shape carries the state; colour only reinforces it. */
.mark { flex: none; width: 0.625rem; height: 0.625rem; border-radius: 50%; transition: background-color var(--fast), border-color var(--fast); }
.mark-ok     { background: var(--ok); }
.mark-bad    { background: var(--bad); border-radius: 1px; transform: rotate(45deg) scale(0.85); }
.mark-busy   { border: 2px solid var(--muted); }
.mark-sample { border: 2px dashed var(--sample); width: 0.75rem; height: 0.75rem; }

.status, .badge { display: inline-flex; align-items: center; gap: var(--s2); }
.badge { font-size: 0.875rem; }
.badge .muted { font-variant-numeric: tabular-nums; }

/* Buttons: one primary, one quiet. Same focus ring as everything else. */
.btn {
  font: inherit; font-size: 0.875rem; font-weight: 550;
  border-radius: 6px; cursor: pointer; touch-action: manipulation;
  transition: background-color var(--fast), border-color var(--fast), color var(--fast);
}
.btn-primary { min-height: 2.25rem; padding: 0 var(--s4); border: 0; background: var(--accent); color: var(--on-accent); }
.btn-quiet   { min-height: 1.75rem; min-width: 4.5rem; padding: 0 var(--s3); border: 1px solid var(--ctrl); background: transparent; color: var(--ink); }
.btn-primary:active:not(:disabled) { background: oklch(0.68 0.12 250); }
.btn-quiet:active:not(:disabled)   { background: var(--line); }
@media (hover: hover) {
  .btn-primary:hover:not(:disabled) { background: oklch(0.79 0.11 250); }
  .btn-quiet:hover:not(:disabled)   { background: oklch(0.28 0.012 250); border-color: var(--muted); }
}
.btn:disabled { cursor: not-allowed; background: transparent; color: var(--disabled); border: 1px dashed var(--ctrl); }
.btn-primary:disabled { padding: 0 calc(var(--s4) - 1px); }

/* Notices sit inline, next to what they explain, and stay until the state changes. */
.notice, .feedback { display: flex; align-items: baseline; gap: var(--s3); margin: 0 0 var(--s4); font-size: 0.875rem; }
.notice {
  padding: var(--s3) var(--s4);
  border: 1px dashed var(--sample); border-radius: 8px;
  background: var(--surface);
}
.notice .mark { align-self: center; }
.notice[hidden], .feedback:empty { display: none; }

/* Runs table */
.table-wrap { overflow-x: auto; border: 1px solid var(--line); border-radius: 8px; background: var(--surface); }
table { width: 100%; min-width: 36rem; border-collapse: collapse; font-size: 0.875rem; }
caption { display: flex; align-items: baseline; gap: var(--s3); padding: var(--s4) var(--s4) var(--s3); text-align: start; }
h2 { margin: 0; font-size: 1rem; font-weight: 600; }
th, td { padding: var(--s2) var(--s4); height: 2.75rem; text-align: start; white-space: nowrap; }
thead th { height: auto; padding-block: var(--s2); font-size: 0.8125rem; font-weight: 500; color: var(--muted); border-bottom: 1px solid var(--line); }
tbody tr + tr > * { border-top: 1px solid var(--line); }
tbody th { font-weight: 500; }
.id { font-family: ui-monospace, "Cascadia Mono", "SF Mono", Menlo, monospace; font-size: 0.8125rem; }
.num { text-align: end; font-variant-numeric: tabular-nums; }
.act { width: 1%; text-align: end; }
tr.is-failed > * { background: var(--failed-row); }
tr.is-failed .status { color: var(--bad); font-weight: 550; }
@media (hover: hover) { tbody tr:not(.skeleton):hover > * { background: oklch(0.25 0.012 250); } }

td.empty { height: 6rem; text-align: center; color: var(--muted); white-space: normal; }

.skeleton span { display: block; height: 0.625rem; width: 70%; border-radius: 3px; background: var(--line); }
.skeleton td:last-child span { width: 3.5rem; margin-inline-start: auto; height: 1.75rem; }

@media (max-width: 40rem) {
  .bar, main { padding-inline: var(--s4); }
}

